   307	    /// @notice Converts an active pending deposit into shares.
   308	    /// @param user The address that requested the deposit
   309	    /// @param epoch The epoch in which the deposit was requested
   310	    function executeDeposit(address user, uint256 epoch) external {
   311	        if (epoch >= depositEpoch) revert EpochNotFulfilled();
   312	
   313	        uint256 queuedDepositAmount = queuedDeposit[user][epoch];
   314	        queuedDeposit[user][epoch] = 0;
   315	
   316	        DepositEpochState memory _depositEpochState = depositEpochState[epoch];
   317	
   318	        uint256 userAssetsDeposited = Math.mulDiv(
   319	            queuedDepositAmount,
   320	            _depositEpochState.assetsFulfilled,
   321	            _depositEpochState.assetsDeposited
   322	        );
   323	
   324	        uint256 sharesReceived = Math.mulDiv(
   325	            userAssetsDeposited,
   326	            _depositEpochState.sharesReceived,
   327	            _depositEpochState.assetsFulfilled
   328	        );
   329	
   330	        // shares from pending deposits are already added to the supply at the start of every new epoch
   331	        _mintVirtual(user, sharesReceived);
   332	
   333	        userBasis[user] += userAssetsDeposited;
   334	
   335	        queuedDeposit[user][epoch] = 0;
   336	
   337	        uint256 assetsRemaining = queuedDepositAmount - userAssetsDeposited;
   338	
   339	        // move remainder of deposit to next epoch -- unfulfilled assets in this epoch will be handled in the next epoch
   340	        if (assetsRemaining > 0) queuedDeposit[user][epoch + 1] += uint128(assetsRemaining);
   341	
   342	        emit DepositExecuted(user, userAssetsDeposited, sharesReceived, epoch);
   343	    }
